package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.*;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnExpression;import org.springframework.security.core.Authentication;import org.springframework.util.function.ThrowingSupplier;
/** Explicit original-owner cancellation; this route does not claim provider cancellation support. */
@RestController @ConditionalOnExpression("${medical.model-runtime.enabled:false} and ${medical.formal-invocation.enabled:false}")
public final class FormalInvocationApplicationController {
 private final ApplicationSessionIdentity identities;private final EnterpriseAccess access;private final FormalInvocationCancellation cancellations;private final FormalInvocationHttpSchema schema;
 public FormalInvocationApplicationController(ApplicationSessionIdentity identities,EnterpriseAccess access,FormalInvocationCancellation cancellations,FormalInvocationHttpSchema schema){this.identities=identities;this.access=access;this.cancellations=cancellations;this.schema=schema;}
 @PostMapping(value="/api/formal-invocation-cancellations",consumes="application/json")
 public JsonNode cancel(HttpServletRequest request,HttpServletResponse response,Authentication authentication)throws Exception{
  var identity=identities.requireCurrent(request,authentication);for(String h:java.util.List.of("X-Schema-Version","X-Context-Revision","Idempotency-Key")){var v=request.getHeaders(h);if(v==null||!v.hasMoreElements())throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);v.nextElement();if(v.hasMoreElements())throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);}if(!"1.0.0".equals(request.getHeader("X-Schema-Version"))||request.getQueryString()!=null)throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);
  var b=schema.read("Cancel",FormalInvocationController.body(request));var receipt=access.execute(identity,a->ThrowingSupplier.of(()->{if(!a.context().context_revision().equals(request.getHeader("X-Context-Revision")))throw new TenantAccessException(ErrorCode.CONTEXT_CHANGED);return cancellations.cancel(a,b.required("invocation_id").textValue(),request.getHeader("Idempotency-Key"),b.required("reason").textValue());}).get());schema.validate("CancelReceipt",receipt);return FormalInvocationResponses.envelope(receipt,"1",response);
 }
 @GetMapping("/api/formal-invocation-cancellation-operations")
 public JsonNode recover(HttpServletRequest request,HttpServletResponse response,Authentication authentication)throws Exception{
  var identity=identities.requireCurrent(request,authentication);for(String h:java.util.List.of("X-Schema-Version","X-Context-Revision","Idempotency-Key")){var v=request.getHeaders(h);if(v==null||!v.hasMoreElements())throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);v.nextElement();if(v.hasMoreElements())throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);}if(!"1.0.0".equals(request.getHeader("X-Schema-Version"))||request.getQueryString()!=null)throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);
  var receipt=access.execute(identity,a->ThrowingSupplier.of(()->{if(!a.context().context_revision().equals(request.getHeader("X-Context-Revision")))throw new TenantAccessException(ErrorCode.CONTEXT_CHANGED);return cancellations.recover(a,request.getHeader("Idempotency-Key"));}).get());var data=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("found",receipt.isPresent());if(receipt.isPresent())data.set("receipt",receipt.get());else data.putNull("receipt");schema.validate("CancelRecovery",data);return FormalInvocationResponses.envelope(data,receipt.isPresent()?"1":null,response);
 }
 @ExceptionHandler(TenantAccessException.class)void denied(TenantAccessException e,HttpServletResponse response)throws java.io.IOException{new IdentityErrorResponseWriter().write(response,e.code()==ErrorCode.ACCESS_DENIED?403:409,e.code());}
}
